def f(D):
    h,w=len(D),len(D[0]); ph,pw=h//2,w//2
    O=[]
    for r in range(h//2):
        row=[]
        for c in range(w//2):
            cnt={}
            for qr in (0,1):
                for qc in (0,1):
                    S=[row2[qc*pw:(qc+1)*pw] for row2 in D[qr*ph:(qr+1)*ph]]
                    for x in set(v for row2 in S for v in row2):
                        cnt[x]=cnt.get(x,0)+S.count([v for v in row2 if v==x].count(x))
            # simpler: total counts across 4 quads
            totals={}
            for qr in (0,1):
                for qc in (0,1):
                    for x in set(v for row2 in D[qr*ph:(qr+1)*ph] for row2 for v in row2[qc*pw:(qc+1)*pw]):
                        totals[x]+=sum(row2[qc*pw:(qc+1)*pw].count(x) for row2 in D[qr*ph:(qr+1)*ph])
            m=min(totals,key=totals.get)
            row.append(m)
        O.append(row)
    return O
